using InterviewAPI.DTOs.Session;
using InterviewAPI.Services;
using Microsoft.AspNetCore.Mvc;
using Moq;
using Xunit;

namespace InterviewAPI.Tests;

public class GenerateQuestionUtcidTests
{
 [Fact(DisplayName="FUNC054-USR-UTCID01")] public async Task Returns_contextual_question(){var(c,s,_,_,u)=MediaTest.Create();var id=Guid.NewGuid();s.Setup(x=>x.GenerateQuestionAsync(u,id,It.IsAny<CancellationToken>())).ReturnsAsync(new GenerateQuestionResponse{Content="Explain DI",OrderIndex=1});var ok=Assert.IsType<OkObjectResult>(await c.GenerateQuestion(id,default));Assert.Equal("Explain DI",Assert.IsType<InterviewAPI.DTOs.ApiResponse<GenerateQuestionResponse>>(ok.Value).Data!.Content);}
 [Fact(DisplayName="FUNC054-USR-UTCID02")] public async Task Business_rule_returns_bad_request(){var(c,s,_,_,_)=MediaTest.Create();s.Setup(x=>x.GenerateQuestionAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<CancellationToken>())).ThrowsAsync(new InvalidOperationException("not ready"));Assert.IsType<BadRequestObjectResult>(await c.GenerateQuestion(Guid.NewGuid(),default));}
 [Fact(DisplayName="FUNC054-USR-UTCID03")] public async Task Missing_identity_returns_service_unavailable(){var(c,s,_,_,_)=MediaTest.Create(false);Assert.Equal(503,MediaTest.Status(await c.GenerateQuestion(Guid.NewGuid(),default)));s.Verify(x=>x.GenerateQuestionAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<CancellationToken>()),Times.Never);}
 [Fact(DisplayName="FUNC054-USR-UTCID04")] public async Task Guard_status_and_retry_are_preserved(){var(c,s,_,_,_)=MediaTest.Create();s.Setup(x=>x.GenerateQuestionAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<CancellationToken>())).ThrowsAsync(new SessionGuardException(429,"cooldown","wait",7));Assert.Equal(429,MediaTest.Status(await c.GenerateQuestion(Guid.NewGuid(),default)));Assert.Equal("7",c.Response.Headers.RetryAfter);}
 [Fact(DisplayName="FUNC054-USR-UTCID05")] public async Task Guid_boundaries_are_forwarded(){var(c,s,_,_,_)=MediaTest.Create();s.Setup(x=>x.GenerateQuestionAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<CancellationToken>())).ReturnsAsync(new GenerateQuestionResponse());Assert.Equal(200,MediaTest.Status(await c.GenerateQuestion(Guid.Empty,default)));Assert.Equal(200,MediaTest.Status(await c.GenerateQuestion(Guid.Parse("ffffffff-ffff-ffff-ffff-ffffffffffff"),default)));}
 [Fact(DisplayName="FUNC054-USR-UTCID06")] public async Task Payment_outage_returns_service_unavailable(){var(c,s,_,_,_)=MediaTest.Create();s.Setup(x=>x.GenerateQuestionAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<CancellationToken>())).ThrowsAsync(new CreditServiceUnavailableException());Assert.Equal(503,MediaTest.Status(await c.GenerateQuestion(Guid.NewGuid(),default)));}
}

public class SendMessageUtcidTests
{
 [Fact(DisplayName="FUNC055-USR-UTCID01")] public async Task Sends_answer_and_returns_progress(){var(c,s,_,_,u)=MediaTest.Create();var id=Guid.NewGuid();var req=new SendMessageRequest{SessionQuestionId=Guid.NewGuid(),Content="answer"};s.Setup(x=>x.SendMessageAsync(u,id,req,It.IsAny<CancellationToken>())).ReturnsAsync(new MessageResponse{AnsweredQuestions=1,TotalQuestions=5});Assert.Equal(200,MediaTest.Status(await c.SendMessage(id,req,default)));}
 [Fact(DisplayName="FUNC055-USR-UTCID02")] public async Task Empty_content_rule_is_safely_mapped(){var(c,s,_,_,_)=MediaTest.Create();s.Setup(x=>x.SendMessageAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<SendMessageRequest>(),It.IsAny<CancellationToken>())).ThrowsAsync(new InvalidOperationException("content"));Assert.Equal(503,MediaTest.Status(await c.SendMessage(Guid.NewGuid(),new SendMessageRequest(),default)));}
 [Fact(DisplayName="FUNC055-USR-UTCID03")] public async Task Missing_identity_prevents_send(){var(c,s,_,_,_)=MediaTest.Create(false);Assert.Equal(503,MediaTest.Status(await c.SendMessage(Guid.NewGuid(),new SendMessageRequest(),default)));s.Verify(x=>x.SendMessageAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<SendMessageRequest>(),It.IsAny<CancellationToken>()),Times.Never);}
 [Fact(DisplayName="FUNC055-USR-UTCID04")] public async Task Guard_conflict_is_preserved(){var(c,s,_,_,_)=MediaTest.Create();s.Setup(x=>x.SendMessageAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<SendMessageRequest>(),It.IsAny<CancellationToken>())).ThrowsAsync(new SessionGuardException(409,"timed_out","ended"));Assert.Equal(409,MediaTest.Status(await c.SendMessage(Guid.NewGuid(),new SendMessageRequest(),default)));}
 [Fact(DisplayName="FUNC055-USR-UTCID05")] public async Task Response_time_boundaries_are_forwarded(){var(c,s,_,_,_)=MediaTest.Create();s.Setup(x=>x.SendMessageAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<SendMessageRequest>(),It.IsAny<CancellationToken>())).ReturnsAsync(new MessageResponse());Assert.Equal(200,MediaTest.Status(await c.SendMessage(Guid.NewGuid(),new SendMessageRequest{ResponseTimeMs=0},default)));Assert.Equal(200,MediaTest.Status(await c.SendMessage(Guid.NewGuid(),new SendMessageRequest{ResponseTimeMs=int.MaxValue},default)));}
 [Fact(DisplayName="FUNC055-USR-UTCID06")] public async Task Dependency_failure_returns_service_unavailable(){var(c,s,_,_,_)=MediaTest.Create();s.Setup(x=>x.SendMessageAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<SendMessageRequest>(),It.IsAny<CancellationToken>())).ThrowsAsync(new Exception("db"));Assert.Equal(503,MediaTest.Status(await c.SendMessage(Guid.NewGuid(),new SendMessageRequest(),default)));}
}

public class DeleteSessionUtcidTests
{
