 [Fact(DisplayName="FUNC056-USR-UTCID03")] public async Task Missing_identity_returns_service_unavailable(){var(c,s,_,_,_)=MediaTest.Create(false);Assert.Equal(503,MediaTest.Status(await c.Delete(Guid.NewGuid(),default)));s.Verify(x=>x.SoftDeleteAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<CancellationToken>()),Times.Never);}
 [Fact(DisplayName="FUNC056-USR-UTCID04")] public async Task Foreign_session_returns_not_found(){var(c,s,_,_,_)=MediaTest.Create();s.Setup(x=>x.SoftDeleteAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<CancellationToken>())).ThrowsAsync(new InvalidOperationException("Session not found."));Assert.IsType<NotFoundObjectResult>(await c.Delete(Guid.NewGuid(),default));}
 [Fact(DisplayName="FUNC056-USR-UTCID05")] public async Task Guid_boundaries_are_forwarded(){var(c,_,_,_,_)=MediaTest.Create();Assert.IsType<NoContentResult>(await c.Delete(Guid.Empty,default));Assert.IsType<NoContentResult>(await c.Delete(Guid.Parse("ffffffff-ffff-ffff-ffff-ffffffffffff"),default));}
 [Fact(DisplayName="FUNC056-USR-UTCID06")] public async Task Database_failure_returns_service_unavailable(){var(c,s,_,_,_)=MediaTest.Create();s.Setup(x=>x.SoftDeleteAsync(It.IsAny<Guid>(),It.IsAny<Guid>(),It.IsAny<CancellationToken>())).ThrowsAsync(new Exception("db"));Assert.Equal(503,MediaTest.Status(await c.Delete(Guid.NewGuid(),default)));}
}

